INSERT INTO `annonces` (`id`, `titre`, `contenu`, `sender_role`, `sender_id`, `dest_type`, `dest_id`, `created_at`) VALUES
(1, 'Absence', 'Bonjour monsieur le directeur, je tiens à vous informer que aujourd\'hui mon enfant masanka muluba gradi ne sera pas présent à l\'école suite à une maladie.\r\nMerci pour votre compréhension et rigueur que vous tenez à nos enfants', 'eleve', 723, 'user', 28, '2026-04-16 07:11:16'),
(2, 'Absence', 'Bonjour monsieur le directeur je tiens à vous informer que votre élève qui est mon enfant ne sera pas présent à l\'école, parceque il est malade.\r\n   Merci', 'eleve', 760, 'user', 28, '2026-04-16 07:12:50'),
(3, 'Absence', 'Bonjour monsieur le directeur je tiens à vous informer que mon enfant qui votre élève au nom de masanka masanka Jessica ne sera pas présent aujourd\'hui parceque elle est malade.\r\nMerci pour la compréhension', 'eleve', 761, 'user', 28, '2026-04-16 07:14:41'),
(4, 'Proclamation', 'Est-ce que la proclamation passera en ligne ?', 'eleve', 595, 'user', 28, '2026-07-01 14:14:58');
